  "privacy.title": "Privacidad",
  "privacy.subtitle": "Cómo maneja Mise los datos del restaurante en esta beta.",
  "privacy.subtitleRestaurant": "{restaurant} · privacidad de la beta",
  "privacy.backToSettings": "Volver a ajustes",
  "privacy.backToLogin": "Volver a iniciar sesión",
  "privacy.beta.title": "Beta solo por invitación del 3 de agosto",
  "privacy.beta.body": "Esta divulgación cubre la beta TestFlight del 3 de agosto de 2026. La sincronización de Square, el envío a proveedores por Gmail, la IA generativa, la facturación y los pedidos autónomos permanecen desactivados.",
  "privacy.summary.title": "Los datos del restaurante permanecen en tu espacio",
  "privacy.summary.body": "Mise usa la cuenta y los datos operativos del restaurante solo para inventario, hallazgos, borradores y acceso del equipo en tu espacio con sesión iniciada.",
  "privacy.section.collect": "Qué recopilamos en esta beta",
  "privacy.section.collectBody": "Correo y perfil de cuenta, perfil del restaurante, inventario, recetas, ventas CSV o manuales, borradores de proveedores, membresías del equipo, comentarios de hallazgos y, si está configurado, diagnósticos depurados de fallos o producto.",
  "privacy.section.notActive": "No activo en esta beta",
  "privacy.section.notActiveBody": "Mise no ejecuta sincronización live de Square, no envía correo a proveedores por Gmail ni otro proveedor de entrega, no genera hallazgos con IA, no factura participación de ahorros ni realiza pedidos autónomos durante esta beta.",
  "privacy.section.storage": "Almacenamiento y acceso",
  "privacy.section.storageBody": "Los datos alojados se guardan en Supabase con controles por restaurante. Los datos demo pueden permanecer solo en este dispositivo. Las credenciales de proveedores y los registros de seguridad privados nunca se incluyen en las exportaciones.",
  "privacy.section.rights": "Exportación y eliminación",
  "privacy.section.rightsBody": "Propietarios y administradores pueden exportar datos operativos desde Ajustes. Cualquier usuario con sesión puede eliminar su cuenta en Ajustes → Cuenta. Los restaurantes de un solo propietario se eliminan con esa cuenta; los compartidos permanecen con otros propietarios.",
  "privacy.section.contact": "Contacto de privacidad",
  "privacy.section.contactBody": "Usa privacy@getmise.app para preguntas de privacidad. La publicación de https://getmise.app/privacy y la supervisión de la bandeja aún requieren confirmación de Raymond y no se presentan aquí como activas.",
  "privacy.hosting.title": "Página pública de privacidad pendiente",
  "privacy.hosting.body": "Abrir la URL de privacidad usa la dirección pública prevista. La publicación aún está pendiente de confirmación de Raymond, así que la página no se considera activa solo porque este botón apunta a esa URL.",
  "privacy.link.errorTitle": "No se pudo abrir la página de privacidad",
  "privacy.link.unavailable": "Este dispositivo no pudo abrir https://getmise.app/privacy. Copia esa dirección más tarde o usa Soporte para escribir a privacy@getmise.app.",
  "privacy.action.openPolicyUrl": "Abrir URL de política de privacidad",
  "privacy.action.openPolicyUrlAccessibility": "Abrir https://getmise.app/privacy",
  "privacy.action.openPolicyUrlHint": "Abre la dirección pública prevista de la política de privacidad si el dispositivo puede abrir enlaces https",
  "privacy.action.openSupport": "Abrir soporte",
  "privacy.action.openExport": "Abrir exportación del restaurante",
