  "support.beta.body": "Esta beta es solo por invitación. La supervisión de la URL pública de soporte está pendiente de confirmación de Raymond y no se presenta aquí como activa.",
  "support.summary.title": "Cómo obtener ayuda",
  "support.summary.body": "Usa esta pantalla para los límites de la beta y Ajustes para exportar o eliminar la cuenta. Los gerentes revisan borradores de proveedores en Mise y se comunican fuera de la app.",
  "support.section.available": "Disponible ahora",
  "support.section.availableBody": "Inicio de sesión, configuración del restaurante, inventario, hallazgos, comentarios de gerentes, borradores de pedidos para copiar o exportar, exportación para propietarios/administradores, roles de equipo y eliminación de cuenta.",
