  "support.section.contact": "Estado del contacto",
  "support.section.contactBody": "Escribe a support@getmise.app para ayuda del producto o a privacy@getmise.app para solicitudes de privacidad. La supervisión de esas bandejas aún requiere confirmación de Raymond y no se presenta aquí como activa.",
  "support.monitoring.title": "Supervisión de bandeja pendiente",
