  "privacy.title": "隐私",
  "privacy.subtitle": "本次测试版中 Mise 如何处理餐厅数据。",
  "privacy.subtitleRestaurant": "{restaurant} · 测试版隐私",
  "privacy.backToSettings": "返回设置",
  "privacy.backToLogin": "返回登录",
  "privacy.beta.title": "8 月 3 日仅限邀请的测试版",
  "privacy.beta.body": "本说明适用于 2026 年 8 月 3 日的 TestFlight 测试版。Square 同步、通过 Gmail 发送供应商订单、生成式 AI、计费与自动下单均保持关闭。",
  "privacy.summary.title": "餐厅数据保留在你的工作区",
  "privacy.summary.body": "Mise 仅将账户与餐厅运营数据用于已登录工作区中的库存、发现、草稿与团队访问。",
  "privacy.section.collect": "本次测试版收集的内容",
  "privacy.section.collectBody": "账户邮箱与资料、餐厅资料、库存、食谱、CSV 或手动销售、供应商草稿、团队成员、发现反馈，以及在已配置时经过清理的崩溃或产品诊断。",
  "privacy.section.notActive": "本次测试版未启用",
  "privacy.section.notActiveBody": "本次测试版中，Mise 不会运行实时 Square 同步，不会通过 Gmail 或其他应用内投递发送供应商邮件，不会生成 AI 发现，不会进行节省分成计费，也不会自动向供应商下单。",
  "privacy.section.storage": "存储与访问",
  "privacy.section.storageBody": "托管数据保存在带有餐厅范围访问控制的 Supabase 中。演示数据可仅保存在本设备。供应商凭证与私密安全日志绝不包含在餐厅导出中。",
  "privacy.section.rights": "导出与删除",
  "privacy.section.rightsBody": "所有者和管理员可在设置中导出餐厅运营数据。任何已登录用户可在设置 → 账户中删除账户。唯一个人所有者的餐厅会随删除一并移除；有其他所有者的共享餐厅会保留。",
  "privacy.section.contact": "隐私联系",
  "privacy.section.contactBody": "隐私问题请使用 privacy@getmise.app。https://getmise.app/privacy 的公开发布与收件箱监控仍需 Raymond 确认，此处不宣称其已上线。",
  "privacy.hosting.title": "公开隐私页待发布",
  "privacy.hosting.body": "打开隐私 URL 会使用预定的公开地址。托管仍待 Raymond 确认，因此不能仅因按钮指向该 URL 就宣称页面已上线。",
  "privacy.link.errorTitle": "无法打开隐私页",
